/* covariance.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "covariance.h"

/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)n;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = ((DATA_TYPE) i*j) / M;
}

/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


// Shared global counter for atomic load balancing among threads
atomic_int block_counter;

// Structure to pass arguments to pthread workers
typedef struct {
    int M;
    int N;
    int stride;
    DATA_TYPE float_n;
    DATA_TYPE *dataT;
    DATA_TYPE *cov;
} CovArgs;

// Pthread worker routine for triangular covariance calculation
void* cov_worker(void* arg) {
    CovArgs* args = (CovArgs*)arg;
    int M = args->M;
    int N = args->N;
    int stride = args->stride;
    DATA_TYPE float_n = args->float_n;
    DATA_TYPE *dataT = args->dataT;
    DATA_TYPE (*cov)[M] = (DATA_TYPE (*)[M])args->cov;

    // Outer tile dimensions for blocking
    int Bi = 32;
    int Bj = 64;
    int num_blocks = (M + Bi - 1) / Bi;

    // Dynamic cyclic extraction to guarantee perfect workload distribution
    while (1) {
        int b = atomic_fetch_add(&block_counter, 1);
        if (b >= num_blocks) break;

        int i0 = b * Bi;
        int i_max = i0 + Bi < M ? i0 + Bi : M;

        for (int j0 = i0; j0 < M; j0 += Bj) {
            int j_max = j0 + Bj < M ? j0 + Bj : M;

            if (i0 == j0) {
                // Main logic for diagonal blocks (un-unrolled to simplify triangle bounds handling)
                for (int i = i0; i < i_max; i++) {
                    for (int j = i; j < j_max; j++) {
                        DATA_TYPE sum = SCALAR_VAL(0.0);
                        DATA_TYPE* restrict di = &dataT[i * stride];
                        DATA_TYPE* restrict dj = &dataT[j * stride];

                        #pragma GCC ivdep
                        for (int k = 0; k < N; k++) {
                            sum += di[k] * dj[k];
                        }

                        cov[i][j] = sum / (float_n - SCALAR_VAL(1.0));
                        cov[j][i] = cov[i][j];
                    }
                }
            } else {
                // Heavily optimized logic for off-diagonal blocks
                for (int i = i0; i < i_max; i++) {
                    int j = j0;
                    DATA_TYPE div = (float_n - SCALAR_VAL(1.0));

                    // Unroll the independent `j` dimension by 8
                    // Gives 8 fused-multiply-adds for every 9 memory loads (extremely high FLOP intensity)
                    for (; j <= j_max - 8; j += 8) {
                        DATA_TYPE sum0 = SCALAR_VAL(0.0), sum1 = SCALAR_VAL(0.0);
                        DATA_TYPE sum2 = SCALAR_VAL(0.0), sum3 = SCALAR_VAL(0.0);
                        DATA_TYPE sum4 = SCALAR_VAL(0.0), sum5 = SCALAR_VAL(0.0);
                        DATA_TYPE sum6 = SCALAR_VAL(0.0), sum7 = SCALAR_VAL(0.0);

                        DATA_TYPE* restrict di = &dataT[i * stride];
                        DATA_TYPE* restrict dj0 = &dataT[(j+0) * stride];
                        DATA_TYPE* restrict dj1 = &dataT[(j+1) * stride];
                        DATA_TYPE* restrict dj2 = &dataT[(j+2) * stride];
                        DATA_TYPE* restrict dj3 = &dataT[(j+3) * stride];
                        DATA_TYPE* restrict dj4 = &dataT[(j+4) * stride];
                        DATA_TYPE* restrict dj5 = &dataT[(j+5) * stride];
                        DATA_TYPE* restrict dj6 = &dataT[(j+6) * stride];
                        DATA_TYPE* restrict dj7 = &dataT[(j+7) * stride];

                        #pragma GCC ivdep
                        for (int k = 0; k < N; k++) {
                            DATA_TYPE d_ik = di[k];
                            sum0 += d_ik * dj0[k];
                            sum1 += d_ik * dj1[k];
                            sum2 += d_ik * dj2[k];
                            sum3 += d_ik * dj3[k];
                            sum4 += d_ik * dj4[k];
                            sum5 += d_ik * dj5[k];
                            sum6 += d_ik * dj6[k];
                            sum7 += d_ik * dj7[k];
                        }

                        cov[i][j+0] = sum0 / div; cov[j+0][i] = cov[i][j+0];
                        cov[i][j+1] = sum1 / div; cov[j+1][i] = cov[i][j+1];
                        cov[i][j+2] = sum2 / div; cov[j+2][i] = cov[i][j+2];
                        cov[i][j+3] = sum3 / div; cov[j+3][i] = cov[i][j+3];
                        cov[i][j+4] = sum4 / div; cov[j+4][i] = cov[i][j+4];
                        cov[i][j+5] = sum5 / div; cov[j+5][i] = cov[i][j+5];
                        cov[i][j+6] = sum6 / div; cov[j+6][i] = cov[i][j+6];
                        cov[i][j+7] = sum7 / div; cov[j+7][i] = cov[i][j+7];
                    }

                    // Tail loop handler for any remainder elements
                    for (; j < j_max; j++) {
                        DATA_TYPE sum = SCALAR_VAL(0.0);
                        DATA_TYPE* restrict di = &dataT[i * stride];
                        DATA_TYPE* restrict dj = &dataT[j * stride];

                        #pragma GCC ivdep
                        for (int k = 0; k < N; k++) {
                            sum += di[k] * dj[k];
                        }

                        cov[i][j] = sum / div;
                        cov[j][i] = cov[i][j];
                    }
                }
            }
        }
    }
    return NULL;
}

/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
#pragma scop

  // Phase 1: Determine local array means sequentially; memory bandwidth bound thus scales well in single core context
  for (int j = 0; j < _PB_M; j++) {
      mean[j] = SCALAR_VAL(0.0);
  }

  // Iterate `i` then `j` locally preserves cache line stride-1 fetches
  for (int i = 0; i < _PB_N; i++) {
      for (int j = 0; j < _PB_M; j++) {
          mean[j] += data[i][j];
      }
  }

  for (int j = 0; j < _PB_M; j++) {
      mean[j] /= float_n;
  }

  // Phase 2: Create a workspace cache-safe row-transposition representation buffer
  int stride = _PB_N;
  if (stride % 16 == 0) stride += 8; // Offset buffer to systematically prevent L1 cache aliasing

  DATA_TYPE *dataT = (DATA_TYPE*) malloc(sizeof(DATA_TYPE) * _PB_M * stride);

  // Mean centering natively fused with 64x64 cache-blocking transpositions
  for (int i = 0; i < _PB_N; i += 64) {
      for (int j = 0; j < _PB_M; j += 64) {
          int i_max = i + 64 < _PB_N ? i + 64 : _PB_N;
          int j_max = j + 64 < _PB_M ? j + 64 : _PB_M;
          for (int ii = i; ii < i_max; ii++) {
              for (int jj = j; jj < j_max; jj++) {
                  DATA_TYPE centered = data[ii][jj] - mean[jj];
                  data[ii][jj] = centered;
                  dataT[jj * stride + ii] = centered;
              }
          }
      }
  }

  // Phase 3: Launch threads (fallback mechanism on environments rejecting implicit `-fopenmp` pragmas)
  #define NUM_THREADS 64
  pthread_t threads[NUM_THREADS];
  CovArgs args;
  args.M = _PB_M;
  args.N = _PB_N;
  args.stride = stride;
  args.float_n = float_n;
  args.dataT = dataT;
  args.cov = (DATA_TYPE*)cov;

  atomic_store(&block_counter, 0);

  for (int t = 0; t < NUM_THREADS; t++) {
      pthread_create(&threads[t], NULL, cov_worker, &args);
  }

  for (int t = 0; t < NUM_THREADS; t++) {
      pthread_join(threads[t], NULL);
  }

  free(dataT);

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
		     POLYBENCH_ARRAY(data),
		     POLYBENCH_ARRAY(cov),
		     POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
