static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

#pragma scop

  /* Initialization of mean */
  for (j = 0; j < _PB_M; j++) {
    mean[j] = SCALAR_VAL(0.0);
  }

  /* Cache efficient row-wise traversal to compute means */
  for (i = 0; i < _PB_N; i++) {
    #pragma GCC ivdep
    for (j = 0; j < _PB_M; j++) {
      mean[j] += data[i][j];
    }
  }

  for (j = 0; j < _PB_M; j++) {
    mean[j] /= float_n;
  }

  /* Cache efficient row-wise normalization of data */
  for (i = 0; i < _PB_N; i++) {
    #pragma GCC ivdep
    for (j = 0; j < _PB_M; j++) {
      data[i][j] -= mean[j];
    }
  }

  /* Initialization of cov */
  for (i = 0; i < _PB_M; i++) {
    #pragma GCC ivdep
    for (j = i; j < _PB_M; j++) {
      cov[i][j] = SCALAR_VAL(0.0);
    }
  }

  // Tiling footprint designed to perfectly hold into the L2 Cache boundaries
  int TI = 32;

  /* Covariance accumulation with Tiling and Register Blocking */
  for (int ii = 0; ii < _PB_M; ii += TI) {
    int i_max = (ii + TI < _PB_M) ? ii + TI : _PB_M;

    for (k = 0; k < _PB_N; k++) {

      // Diagonal triangle blocks handling
      for (i = ii; i < i_max; i++) {
        DATA_TYPE d = data[k][i];
        #pragma GCC ivdep
        for (j = i; j < i_max; j++) {
          cov[i][j] += d * data[k][j];
        }
      }

      // Computation-heavy Off-diagonal rectangle blocks loop
      int i_idx = ii;

      // Hand-unrolled by 4 on the row dimension to leverage parallel Vector Instruction FMAs
      for (; i_idx <= i_max - 4; i_idx += 4) {
        DATA_TYPE d0 = data[k][i_idx];
        DATA_TYPE d1 = data[k][i_idx+1];
        DATA_TYPE d2 = data[k][i_idx+2];
        DATA_TYPE d3 = data[k][i_idx+3];

        #pragma GCC ivdep
        for (j = i_max; j < _PB_M; j++) {
          DATA_TYPE dj = data[k][j];
          cov[i_idx][j]   += d0 * dj;
          cov[i_idx+1][j] += d1 * dj;
          cov[i_idx+2][j] += d2 * dj;
          cov[i_idx+3][j] += d3 * dj;
        }
      }

      // Unroll tail handling
      for (; i_idx < i_max; i_idx++) {
        DATA_TYPE d = data[k][i_idx];
        #pragma GCC ivdep
        for (j = i_max; j < _PB_M; j++) {
          cov[i_idx][j] += d * data[k][j];
        }
      }
    }
  }

  /* Final division scale and mirrored symmetry copy over the lower triangle */
  DATA_TYPE denom = float_n - SCALAR_VAL(1.0);
  for (i = 0; i < _PB_M; i++) {
    for (j = i; j < _PB_M; j++) {
      cov[i][j] /= denom;
      cov[j][i] = cov[i][j];
    }
  }

#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
