/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
#pragma scop

  /* 
   * Optimization 1: Combine Mean Calculation and Centering.
   * By computing the mean and immediately centering the data column-by-column 
   * within blocks (TILE_J), we ensure that the accessed subset of `data` 
   * remains in the L2 cache for both passes. OpenMP ensures columns are parallelized.
   */
  #define TILE_J 128
  int num_blocks_j = (_PB_M + TILE_J - 1) / TILE_J;

  #pragma omp parallel for schedule(dynamic)
  for (int block = 0; block < num_blocks_j; block++) {
      int jj = block * TILE_J;
      int j_max = (jj + TILE_J < _PB_M) ? (jj + TILE_J) : _PB_M;

      for (int j = jj; j < j_max; j++) {
          mean[j] = SCALAR_VAL(0.0);
      }

      for (int i = 0; i < _PB_N; i++) {
          #pragma GCC ivdep
          for (int j = jj; j < j_max; j++) {
              mean[j] += data[i][j];
          }
      }

      for (int j = jj; j < j_max; j++) {
          mean[j] /= float_n;
      }

      for (int i = 0; i < _PB_N; i++) {
          #pragma GCC ivdep
          for (int j = jj; j < j_max; j++) {
              data[i][j] -= mean[j];
          }
      }
  }


  /* 
   * Optimization 2: Tiled Covariance Matrix computation with inner-loop K unrolling.
   * Standard A^T * A matrix multiplication optimization.
   * We block the i, j, and k loops to maximize cache reuse.
   */
  #define TILE_I 64
  #define TILE_K 64

  int num_blocks_i = (_PB_M + TILE_I - 1) / TILE_I;
  int total_blocks = num_blocks_i * num_blocks_j;

  /* We linearize the blocked grid so OpenMP dynamically balances execution without race conditions. */
  #pragma omp parallel for schedule(dynamic)
  for (int block = 0; block < total_blocks; block++) {
      int ii = (block / num_blocks_j) * TILE_I;
      int jj = (block % num_blocks_j) * TILE_J;

      // We strictly compute the upper triangle to maintain symmetry rules.
      int jj_start = (ii / TILE_J) * TILE_J;
      if (jj < jj_start) continue;

      int i_max = (ii + TILE_I < _PB_M) ? (ii + TILE_I) : _PB_M;
      int j_max = (jj + TILE_J < _PB_M) ? (jj + TILE_J) : _PB_M;

      /* Initialize the block within cov */
      for (int i = ii; i < i_max; i++) {
          int j_start = (jj > i) ? jj : i;
          #pragma GCC ivdep
          for (int j = j_start; j < j_max; j++) {
              cov[i][j] = SCALAR_VAL(0.0);
          }
      }

      /* Core accumulated matrix multiplication phase. */
      for (int kk = 0; kk < _PB_N; kk += TILE_K) {
          int k_max = (kk + TILE_K < _PB_N) ? (kk + TILE_K) : _PB_N;

          for (int i = ii; i < i_max; i++) {
              int j_start = (jj > i) ? jj : i;
              int k = kk;

              /* 
               * Register Blocking: Manually unrolling the k loop allows the compiler to
               * keep `cov[i][j]` inside vector registers for 8 FMAs simultaneously, 
               * dramatically boosting the arithmetic intensity!
