              for (; k <= k_max - 8; k += 8) {
                  DATA_TYPE d0 = data[k][i];
                  DATA_TYPE d1 = data[k+1][i];
                  DATA_TYPE d2 = data[k+2][i];
                  DATA_TYPE d3 = data[k+3][i];
                  DATA_TYPE d4 = data[k+4][i];
                  DATA_TYPE d5 = data[k+5][i];
                  DATA_TYPE d6 = data[k+6][i];
                  DATA_TYPE d7 = data[k+7][i];

                  #pragma GCC ivdep
                  #pragma GCC unroll 8
                  for (int j = j_start; j < j_max; j++) {
                      cov[i][j] += d0 * data[k][j] 
                                 + d1 * data[k+1][j] 
                                 + d2 * data[k+2][j] 
                                 + d3 * data[k+3][j]
                                 + d4 * data[k+4][j] 
                                 + d5 * data[k+5][j] 
                                 + d6 * data[k+6][j] 
                                 + d7 * data[k+7][j];
                  }
              }

              /* Process remainder k unrolled by 4 */
              for (; k <= k_max - 4; k += 4) {
                  DATA_TYPE d0 = data[k][i];
                  DATA_TYPE d1 = data[k+1][i];
                  DATA_TYPE d2 = data[k+2][i];
                  DATA_TYPE d3 = data[k+3][i];

                  #pragma GCC ivdep
                  #pragma GCC unroll 4
                  for (int j = j_start; j < j_max; j++) {
                      cov[i][j] += d0 * data[k][j] 
                                 + d1 * data[k+1][j] 
                                 + d2 * data[k+2][j] 
                                 + d3 * data[k+3][j];
                  }
              }

              /* Unroll epilogue for remaining k iterations */
              for (; k < k_max; k++) {
                  DATA_TYPE d0 = data[k][i];
                  #pragma GCC ivdep
                  for (int j = j_start; j < j_max; j++) {
                      cov[i][j] += d0 * data[k][j];
                  }
              }
          }
      }
  }


  /* Optimization 3: Post-processing symmetric assignment avoiding write-contention during computation. */
  DATA_TYPE denom = float_n - SCALAR_VAL(1.0);
  #pragma omp parallel for schedule(dynamic)
  for (int i = 0; i < _PB_M; i++) {
      for (int j = i; j < _PB_M; j++) {
          cov[i][j] /= denom;
          cov[j][i] = cov[i][j];
      }
  }

#pragma endscop
}


